<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ElButton, ElDialog, ElEmpty, ElForm, ElFormItem, ElInput, ElOption, ElSelect, ElSkeleton, ElTable, ElTableColumn, ElTag } from 'element-plus'
import { api, type FinanceAccountRecord, type FinanceLedgerRecord } from './services/api'
const actorId = String(import.meta.env.VITE_ACTOR_ID || '')
const ledgers = ref<FinanceLedgerRecord[]>([]); const accounts = ref<FinanceAccountRecord[]>([]); const selectedLedgerId = ref(''); const loading = ref(false); const accountsLoading = ref(false); const error = ref(''); const toast = ref(''); const dialog = ref(false); const name = ref(''); const currency = ref('CNY')
const selectedLedger = computed(() => ledgers.value.find(item => item.id === selectedLedgerId.value))
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
async function loadAccounts() { if (!actorId || !selectedLedgerId.value) { accounts.value = []; return }; accountsLoading.value = true; try { accounts.value = await api.listFinanceAccounts(selectedLedgerId.value, actorId) } catch { accounts.value = []; notify('账户加载失败，请检查后端服务') } finally { accountsLoading.value = false } }
async function load() { if (!actorId) { error.value = '未配置当前用户身份，无法加载 Finance 数据'; return }; loading.value = true; error.value = ''; try { ledgers.value = await api.listFinanceLedgers(actorId); if (!selectedLedgerId.value || !ledgers.value.some(item => item.id === selectedLedgerId.value)) selectedLedgerId.value = ledgers.value[0]?.id || ''; await loadAccounts() } catch { ledgers.value = []; accounts.value = []; error.value = '账本 API 加载失败，请检查登录状态或后端服务' } finally { loading.value = false } }
async function createLedger() { if (!name.value.trim()) { notify('请输入账本名称'); return }; if (!actorId) { notify('未配置当前用户身份，无法创建账本'); return }; try { const ledger = await api.createFinanceLedger({ name: name.value.trim(), baseCurrency: currency.value }, actorId); ledgers.value.unshift(ledger); selectedLedgerId.value = ledger.id; name.value = ''; dialog.value = false; await loadAccounts(); notify('账本已创建') } catch (error) { notify(error instanceof Error ? error.message : '账本创建失败') } }
watch(selectedLedgerId, () => { void loadAccounts() }); onMounted(load)
</script>
<template><div class="finance-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">个人记账 · 服务端账本</span><span class="mini-avatar">陈</span></header><main class="catalog-main finance-main"><div class="catalog-heading"><div><p class="eyebrow">个人记账</p><h1>账本总览</h1><p>账本与账户数据来自 Finance 服务端接口，页面不保存本地交易副本。</p></div><div><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" @click="dialog = true">＋ 新建账本</el-button></div></div><nav class="finance-tabs"><RouterLink to="/console/finance" class="active">总览</RouterLink><RouterLink to="/console/finance/accounts">账户</RouterLink><RouterLink to="/console/finance/transactions">交易</RouterLink><RouterLink to="/console/finance/budgets">预算</RouterLink><RouterLink to="/console/finance/reconcile">对账与导入</RouterLink></nav><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" /><el-skeleton v-if="loading" :rows="5" animated /><section v-else class="finance-ledger-layout"><el-card shadow="never" class="surface-card"><template #header><div class="dashboard-card-header"><span>我的账本</span><el-tag type="info">{{ ledgers.length }} 个</el-tag></div></template><el-empty v-if="!ledgers.length" description="暂无可访问账本" /><div v-else class="ledger-list"><el-button v-for="ledger in ledgers" :key="ledger.id" text class="ledger-item" :class="{ active: ledger.id === selectedLedgerId }" @click="selectedLedgerId = ledger.id"><span><b>{{ ledger.name || ledger.id.slice(0, 8) }}</b><small>{{ ledger.baseCurrency || ledger.base_currency || '—' }}</small></span><el-tag :type="ledger.archived ? 'info' : 'success'">{{ ledger.archived ? '已归档' : '正常' }}</el-tag></el-button></div></el-card><el-card shadow="never" class="surface-card"><template #header><div class="dashboard-card-header"><span>{{ selectedLedger?.name || '账户' }}</span><el-tag type="info">{{ accounts.length }} 个</el-tag></div></template><el-table v-loading="accountsLoading" :data="accounts" empty-text="该账本暂无账户"><el-table-column prop="name" label="账户" min-width="180" /><el-table-column prop="type" label="类型" width="130" /><el-table-column prop="currency" label="币种" width="100" /><el-table-column label="当前余额" width="160"><template #default="{ row }">{{ row.currentBalance ?? row.current_balance ?? 0 }}</template></el-table-column><el-table-column prop="maskedIdentifier" label="标识" width="150" /></el-table></el-card></section></main><el-dialog v-model="dialog" title="新建账本" width="460px"><el-form label-position="top"><el-form-item label="账本名称"><el-input v-model="name" maxlength="120" placeholder="例如：家庭账本" @keyup.enter="createLedger" /></el-form-item><el-form-item label="基础币种"><el-select v-model="currency" style="width:100%"><el-option label="人民币（CNY）" value="CNY" /><el-option label="美元（USD）" value="USD" /><el-option label="欧元（EUR）" value="EUR" /></el-select></el-form-item><div class="dialog-actions"><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="createLedger">创建账本</el-button></div></el-form></el-dialog><div v-if="toast" class="snackbar">✓ {{ toast }}<el-button text circle @click="toast = ''">×</el-button></div></div></template>
